Local Ltac pf_tte_err HCc ECc SL FRhi BUF LBB BSZC TMP TMP24 sp L e loc p0 nlen v1 v2 bsz bb :=
  let junk := fresh "junk" in let TMPj := fresh "TMPj" in
  destruct (rw_cells_forget _ _ _ _ TMP) as [junk TMPj]; rewrite TMP24 in TMPj; clear TMP;
  unfold ErrCodeCells, EC_http_loc, ec_make_loc in ECc; cbn [ec_val ec_cat ec_flags Z.eqb] in ECc;
  unfold HE_NEED_MORE, HE_BAD_LINE_ENDING, LOC_TTE_NM, LOC_TTE_NM2, LOC_TTE_BADLE, G_HTTP_CAT, wz in ECc;
  lazymatch goal with XSc : XStatics _ |- _ => expose_statics HCc XSc [(bv_unsigned sp + 40, bv_unsigned sp + 48)]%Z end;
  st1; steps_to 0x3f34c%Z;
  do 13 step;
  lazymatch goal with TL' : rw_cells _ _ (bv_unsigned sp + -136) _, ST' : stk _ _ _ _ |- _ =>
    join_frame TMPj FRhi (bv_unsigned sp + -128); join_frame TL' TMPj (bv_unsigned sp + -136); join_frame SL TL' (bv_unsigned sp + -160);
    step; release_frame SL ST' (bv_unsigned sp); step
  end;
  apply rw_cells_of_u8arr in BUF; rewrite LBB in BUF;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mx _) =>
    assert (BFJ : rw_cells usegs mx (bv_unsigned sp + 48) [C8 (Z_to_bv 64 bsz); CB 4096 bb])
      by (apply (proj2 (rw_cells_app usegs mx (bv_unsigned sp + 48) [C8 (Z_to_bv 64 bsz)] [CB 4096 bb])); split; [exact BSZC|];
          cbn [cells_size csize Nat.add]; replace (bv_unsigned sp + 48 + Z.of_nat 8) with (bv_unsigned sp + 56) by lia; exact BUF)
  end;
  pf_finish L (EC_http_loc e loc) true (Z_to_bv 64 p0) (Z_to_bv 64 nlen) v1 v2 bsz bb;
  [ right; apply pf_fail_exit; [cbn; qtauto | reflexivity | unfold LOC_TTE_NM, LOC_TTE_NM2, LOC_TTE_BADLE; lia | unfold LOC_TTE_NM, LOC_TTE_NM2, LOC_TTE_BADLE; lia]
  | close_HttpCat_chunks
  | lazymatch goal with XSc : XStatics ?my, MU2 : munch _ ?my _, WM2 : wmono _ ?my _ |- _ => close_XStatics XSc MU2 WM2 end ].
